import { AppHypercube3d } from '../02_Hypercube/App/lib/AppHypercube3d';

export class Solution {
	public divHost: HTMLDivElement;
	public appHypercube3d: AppHypercube3d;
	constructor(id: string) {
		this.init(id);
	}
	async init(divID: string) {
		this.appHypercube3d = await AppHypercube3d.init({
			divID,
			webGPU: true,
			performanceMode: false,
			ui: true,
			debuggerMode: true,
		});
	}
	public destroy() {
		this.appHypercube3d.destroy();
	}
}
